.nightmode-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: none;
  z-index: 9999;
  justify-content: center;
  align-items: center;
  color: white;
  font-size: 24px;
  text-align: center;
  pointer-events: auto; /* allows interaction with content behind */
}

.nightmode-overlay.show {
  display: flex;
}

/* Optional: prevent text selection */
.nightmode-overlay::selection {
  background: none;
}
